  (* [comment removed for export] *)
  Lemma page_allowedb_flat_map : forall {T} (f : T -> list (Z * Z)) l p,
    page_allowedb (flat_map f l) p = true -> exists q, In q l /\ page_allowedb (f q) p = true.
Proof.
